  3258  tokenize(ParseCtx *parseCtx, CtxJson *ctx, const UA_ByteString *src) {
  3259      /* Set up the context */
  3260      ctx->pos = &src->data[0];
  3261      ctx->end = &src->data[src->length];
  3262      ctx->depth = 0;
  3263      parseCtx->tokenCount = 0;
  3264      parseCtx->index = 0;
  3265
  3266      /*Set up tokenizer jsmn*/
  3267      jsmn_parser p;
  3268      jsmn_init(&p);
  3269      parseCtx->tokenCount = (UA_Int32)
  3270          jsmn_parse(&p, (char*)src->data, src->length,
  3271                     parseCtx->tokenArray, TOKENCOUNT);
  3272
  3273      if(parseCtx->tokenCount < 0) {
  3274          if(parseCtx->tokenCount == JSMN_ERROR_NOMEM)
  3275              return UA_STATUSCODE_BADOUTOFMEMORY;
  3276          return UA_STATUSCODE_BADDECODINGERROR;
  3277      }
  3278
  3279      return UA_STATUSCODE_GOOD;
  3280  }
