  3290  UA_decodeJson(const UA_ByteString *src, void *dst, const UA_DataType *type) {
  3291
  3292  #ifndef UA_ENABLE_TYPENAMES
  3293      return UA_STATUSCODE_BADNOTSUPPORTED;
  3294  #endif
  3295
  3296      if(dst == NULL || src == NULL || type == NULL) {
  3297          return UA_STATUSCODE_BADARGUMENTSMISSING;
  3298      }
  3299
  3300      /* Set up the context */
  3301      CtxJson ctx;
  3302      ParseCtx parseCtx;
  3303      parseCtx.tokenArray = (jsmntok_t*)UA_malloc(sizeof(jsmntok_t) * TOKENCOUNT);
  3304      if(!parseCtx.tokenArray)
  3305          return UA_STATUSCODE_BADOUTOFMEMORY;
  3306
  3307      status ret = tokenize(&parseCtx, &ctx, src);
  3308      if(ret != UA_STATUSCODE_GOOD)
  3309          goto cleanup;
  3310
  3311      /* Assume the top-level element is an object */
  3312      if(parseCtx.tokenCount < 1 || parseCtx.tokenArray[0].type != JSMN_OBJECT) {
  3313          if(parseCtx.tokenCount == 1) {
  3314              if(parseCtx.tokenArray[0].type == JSMN_PRIMITIVE ||
  3315                 parseCtx.tokenArray[0].type == JSMN_STRING) {
  3316                 /* Only a primitive to parse. Do it directly. */
  3317                 memset(dst, 0, type->memSize); /* Initialize the value */
  3318                 ret = decodeJsonJumpTable[type->typeKind](dst, type, &ctx, &parseCtx, true);
  3319                 goto cleanup;
  3320              }
  3321          }
  3322          ret = UA_STATUSCODE_BADDECODINGERROR;
  3323          goto cleanup;
  3324      }
  3325
  3326      /* Decode */
  3327      memset(dst, 0, type->memSize); /* Initialize the value */
  3328      ret = decodeJsonJumpTable[type->typeKind](dst, type, &ctx, &parseCtx, true);
  3329
  3330      cleanup:
  3331      UA_free(parseCtx.tokenArray);
  3332
  3333      /* sanity check if all Tokens were processed */
  3334      if(!(parseCtx.index == parseCtx.tokenCount ||
  3335           parseCtx.index == parseCtx.tokenCount-1)) {
  3336          ret = UA_STATUSCODE_BADDECODINGERROR;
  3337      }
  3338
  3339      if(ret != UA_STATUSCODE_GOOD)
  3340          UA_deleteMembers(dst, type); /* Clean up */
  3341      return ret;
  3342  }
